package org.eclipse.rdf4j.sail.lmdb;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.OptionalLong;

import org.eclipse.rdf4j.sail.base.SailDatasetTripleTermSource;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsView;
import org.eclipse.rdf4j.sail.lmdb.frontier.LmdbStatisticsService;

/**
 * Owned frontier reads for cost-model tests that use a mocked {@link LmdbEstimatorRuntime}.
 * <p>
 * Only a model that owns a current read selection for its source and snapshot epoch is admitted to mapped (Frontier V2)
 * costing, and it opens its view only through {@link LmdbFrontierReadSelection#openAdmittedView}. A mock runtime
 * returns {@code null} for an unstubbed selection, so a fixture that relies on the selection must model the paired read
 * owner explicitly. Real-store tests exercise the ownership checks themselves.
 */
final class LmdbOwnedFrontierReadTestSupport {

	private LmdbOwnedFrontierReadTestSupport() {
	}

	/**
	 * Returns a model that owns a current selection for a fresh source at {@code epoch}. The selection admits the views
	 * that {@code runtime.statisticsService()} opens for that epoch, so that service must be stubbed first.
	 */
	static LmdbPackedCostModel ownedModel(LmdbEstimatorRuntime runtime, FrontierStatisticsView view, long epoch,
			int planeMask) {
		SailDatasetTripleTermSource source = mock(SailDatasetTripleTermSource.class);
		LmdbFrontierReadSelection selection = ownedSelection(runtime, source, epoch, planeMask);
		admitViews(selection, runtime.statisticsService(), view, epoch);
		return new LmdbPackedCostModel(runtime, OptionalLong.of(epoch), true, source, null);
	}

	/**
	 * Returns the current selection that {@code runtime} hands out for {@code source}. It matches the runtime's value
	 * store (stubbed with a mock if absent) and a physical triple store that this call stubs on the runtime.
	 */
	static LmdbFrontierReadSelection ownedSelection(LmdbEstimatorRuntime runtime, SailDatasetTripleTermSource source,
			long epoch, int planeMask) {
		LmdbFrontierReadSelection selection = mock(LmdbFrontierReadSelection.class);
		when(runtime.frontierPlanningReadSelection(source)).thenReturn(selection);
		when(selection.matchesSource(source)).thenReturn(true);
		when(selection.isCurrent()).thenReturn(true);
		when(selection.isCurrentForSharedEvidence()).thenReturn(true);
		when(selection.snapshotEpoch()).thenReturn(epoch);
		when(selection.population()).thenReturn(LmdbFrontierReadPopulation.STORE_DEFAULTS);
		when(selection.planeMask()).thenReturn(planeMask);

		ValueStore values = runtime.valueStore();
		if (values == null) {
			values = mock(ValueStore.class);
			when(runtime.valueStore()).thenReturn(values);
		}
		TripleStore triples = mock(TripleStore.class);
		when(runtime.physicalTripleStore()).thenReturn(triples);
		when(selection.matchesStores(values, triples)).thenReturn(true);
		return selection;
	}

	/**
	 * Lets {@code selection} admit the view that {@code statistics} opens for {@code epoch} while that view is ready.
	 */
	static void admitViews(LmdbFrontierReadSelection selection, LmdbStatisticsService statistics,
			FrontierStatisticsView view, long epoch) {
		when(selection.ownsAdmittedView(view)).thenReturn(true);
		when(selection.openAdmittedView(statistics)).thenAnswer(invocation -> {
			FrontierStatisticsView opened = statistics.openView(epoch);
			return new LmdbFrontierReadSelection.AdmittedView(opened,
					opened.ready() ? selection : LmdbFrontierReadSelection.UNAVAILABLE);
		});
	}
}
